INSERT INTO lesson_proposals (entry_id, category, suggested_action, reasoning, confidence, status, target_layer, target_artifact, route, proposed_at, status_updated_at, status_updated_by) VALUES (98, 'governance_rule', 'Reconcile PLANNER_TEMPLATE Checklist 14, and the cross-reference in Checklist 22, to Checklist 23: under a declared Scope a path is named in Scope or Deposits and step prose authorizes nothing; the prose clause survives only for plans without a Scope block. Cite Checklist 23; do not codify the rule again.', 'Gate 1 W=30, reader A (gate1-packet-2026-09-13-a.md, governance 1d63939c): the rider on entry 98 (2026-09-08, governance 1f242128, thread 191) narrows the lesson to plans without a Scope block. Proposal 103 holds, but the text it produced (Checklist 14, sources 103 and 121, and Checklist 22) is false for every plan with a declared Scope, which Checklist 23 makes mandatory. Inserted by the executor on the reader routing.', 'high', 'accepted', 'governance', 'PLANNER_TEMPLATE.md', 'codify', strftime('%Y-%m-%dT%H:%M:%SZ','now'), strftime('%Y-%m-%dT%H:%M:%SZ','now'), 'planner');
INSERT INTO lesson_proposals (entry_id, category, suggested_action, reasoning, confidence, status, target_layer, target_artifact, route, proposed_at, status_updated_at, status_updated_by) VALUES (106, 'governance_rule', 'Retire PLANNER_TEMPLATE Workaround 14, or rewrite it to the declaration form cited to Checklist 23: the evidence directory is declared with a trailing slash in Scope or Deposits, and the override is no longer the disposition for this class.', 'Gate 1 W=30, reader A (gate1-packet-2026-09-13-a.md, governance 1d63939c): the rider on entry 106 (2026-09-08, governance 1f242128, thread 208) retires the override that proposal 111 codified. Proposal 111 flips to superseded in this transaction (Rule 101: supersession acts on the proposal record); this proposal carries the doctrine edit. Inserted by the executor on the reader routing.', 'high', 'accepted', 'governance', 'PLANNER_TEMPLATE.md', 'codify', strftime('%Y-%m-%dT%H:%M:%SZ','now'), strftime('%Y-%m-%dT%H:%M:%SZ','now'), 'planner');
